225	/*
226	** This routine is called whenever an out-of-memory condition is seen,
227	** It's only purpose to to serve as a breakpoint for gdb or similar
228	** code debuggers when working on out-of-memory conditions, for example
229	** caused by PRAGMA hard_heap_limit=N.
230	*/
231	static SQLITE_NOINLINE void test_oom_breakpoint(u64 n){
232	  static u64 nOomFault = 0;
233	  nOomFault += n;
234	  /* The assert() is never reached in a human lifetime.  It  is here mostly
235	  ** to prevent code optimizers from optimizing out this function. */
236	  assert( (nOomFault>>32) < 0xffffffff );
237	}
