242	/*
243	** Do a memory allocation with statistics and alarms.  Assume the
244	** lock is already held.
245	*/
246	static void mallocWithAlarm(int n, void **pp){
247	  void *p;
248	  int nFull;
249	  assert( sqlite3_mutex_held(mem0.mutex) );
250	  assert( n>0 );
251	
252	  /* In Firefox (circa 2017-02-08), xRoundup() is remapped to an internal
253	  ** implementation of malloc_good_size(), which must be called in debug
254	  ** mode and specifically when the DMD "Dark Matter Detector" is enabled
255	  ** or else a crash results.  Hence, do not attempt to optimize out the
256	  ** following xRoundup() call. */
257	  nFull = sqlite3GlobalConfig.m.xRoundup(n);
258	
259	  sqlite3StatusHighwater(SQLITE_STATUS_MALLOC_SIZE, n);
260	  if( mem0.alarmThreshold>0 ){
261	    sqlite3_int64 nUsed = sqlite3StatusValue(SQLITE_STATUS_MEMORY_USED);
262	    if( nUsed >= mem0.alarmThreshold - nFull ){
263	      AtomicStore(&mem0.nearlyFull, 1);
264	      sqlite3MallocAlarm(nFull);
265	      if( mem0.hardLimit ){
266	        nUsed = sqlite3StatusValue(SQLITE_STATUS_MEMORY_USED);
267	        if( nUsed >= mem0.hardLimit - nFull ){
268	          test_oom_breakpoint(1);
269	          *pp = 0;
270	          return;
271	        }
272	      }
273	    }else{
274	      AtomicStore(&mem0.nearlyFull, 0);
275	    }
276	  }
277	  p = sqlite3GlobalConfig.m.xMalloc(nFull);
278	#ifdef SQLITE_ENABLE_MEMORY_MANAGEMENT
279	  if( p==0 && mem0.alarmThreshold>0 ){
280	    sqlite3MallocAlarm(nFull);
281	    p = sqlite3GlobalConfig.m.xMalloc(nFull);
282	  }
283	#endif
284	  if( p ){
285	    nFull = sqlite3MallocSize(p);
286	    sqlite3StatusUp(SQLITE_STATUS_MEMORY_USED, nFull);
287	    sqlite3StatusUp(SQLITE_STATUS_MALLOC_COUNT, 1);
288	  }
289	  *pp = p;
290	}
