292	/*
293	** Allocate memory.  This routine is like sqlite3_malloc() except that it
294	** assumes the memory subsystem has already been initialized.
295	*/
296	void *sqlite3Malloc(u64 n){
297	  void *p;
298	  if( n==0 || n>SQLITE_MAX_ALLOCATION_SIZE ){
299	    p = 0;
300	  }else if( sqlite3GlobalConfig.bMemstat ){
301	    sqlite3_mutex_enter(mem0.mutex);
