303	    sqlite3_mutex_leave(mem0.mutex);
304	  }else{
305	    p = sqlite3GlobalConfig.m.xMalloc((int)n);
306	  }
307	  assert( EIGHT_BYTE_ALIGNMENT(p) );  /* IMP: R-11148-40995 */
308	  return p;
309	}
