601	/* Finish the work of sqlite3DbMallocRawNN for the unusual and
602	** slower case when the allocation cannot be fulfilled using lookaside.
603	*/
604	static SQLITE_NOINLINE void *dbMallocRawFinish(sqlite3 *db, u64 n){
605	  void *p;
606	  assert( db!=0 );
607	  p = sqlite3Malloc(n);
608	  if( !p ) sqlite3OomFault(db);
609	  sqlite3MemdebugSetType(p, 
610	         (db->lookaside.bDisable==0) ? MEMTYPE_LOOKASIDE : MEMTYPE_HEAP);
611	  return p;
